+const revokedSessions = new Set<string>();
+const REVOCATION_TTL = 60_000; // 60 seconds
+
+export const markRevoked = (sessionId: string): void => {
+  revokedSessions.add(sessionId);
+  setTimeout(() => revokedSessions.delete(sessionId), REVOCATION_TTL);
+};
+
+export const isRevoked = (sessionId: string): boolean => {
+  return revokedSessions.has(sessionId);
+};
+
+export const getRevokedSessions = (): string[] => {
+  return Array.from(revokedSessions);
+};
+
+export const replaceRevokedSessions = (sessionIds: string[]): void => {
+  revokedSessions.clear();
+  sessionIds.forEach((id) => markRevoked(id));
+};
